<?php
declare(strict_types=1);
require_once __DIR__.'/../../app/bootstrap.php';require_once __DIR__.'/../../app/read_queries.php';header('Cache-Control: no-store');$section=(string)($_GET['seccion']??'');$page=read_page_number($_GET['pagina']??null);$perPage=10;$state=strtoupper((string)($_GET['estado']??''));
try {
if($section==='entregas'){require_permission('ENTREGAS_VER');$state=in_array($state,['ENTREGADA','FALLIDA'],true)?$state:null;$result=read_procedure_list('DECLARE @total_registros INT; EXEC dbo.sp_listar_entregas @estado=?,@viaje_id=NULL,@desde=NULL,@hasta=NULL,@pagina=?,@por_pagina=?,@total_registros=@total_registros OUTPUT; SELECT @total_registros AS total_registros;',[$state,$page,$perPage]);}
elseif($section==='incidencias'){require_permission('INCIDENCIAS_VER');$state=in_array($state,['ABIERTA','EN_ATENCION','RESUELTA'],true)?$state:null;$result=read_procedure_list('DECLARE @total_registros INT; EXEC dbo.sp_listar_incidencias @solicitud_id=NULL,@estado=?,@pagina=?,@por_pagina=?,@total_registros=@total_registros OUTPUT; SELECT @total_registros AS total_registros;',[$state,$page,$perPage]);}
elseif($section==='notificaciones'){require_permission('NOTIFICACIONES_VER');$state=in_array($state,['PENDIENTE','ENVIADA','ERROR'],true)?$state:null;$result=read_procedure_list('DECLARE @total_registros INT; EXEC dbo.sp_listar_notificaciones @solicitud_id=NULL,@estado_envio=?,@desde=NULL,@hasta=NULL,@pagina=?,@por_pagina=?,@total_registros=@total_registros OUTPUT; SELECT @total_registros AS total_registros;',[$state,$page,$perPage]);}
elseif($section==='documentos'){require_permission('DOCUMENTOS_VER');$id=filter_var($_GET['solicitud_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if($id===false){echo empty_state('Selecciona una solicitud','Indica el identificador de una solicitud para consultar sus documentos.');exit;}$result=read_procedure_list('DECLARE @total_registros INT; EXEC dbo.sp_listar_documentos @solicitud_id=?,@pagina=?,@por_pagina=?,@total_registros=@total_registros OUTPUT; SELECT @total_registros AS total_registros;',[$id,$page,$perPage]);}
else{http_response_code(404);exit('Sección no encontrada.');}}
catch(PDOException){read_error_response();}
$total=$result['total'];$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);
?>
<div class="table-container"><table class="table is-fullwidth is-hoverable"><thead><tr><?php if($section==='entregas'):?><th>Solicitud</th><th>Viaje</th><th>Estado</th><th>Receptor efectivo</th><th>Resultado</th><?php elseif($section==='incidencias'):?><th>Solicitud</th><th>Tipo</th><th>Estado</th><th>Responsable</th><th>Reporte</th><th></th><?php elseif($section==='notificaciones'):?><th>Solicitud</th><th>Evento</th><th>Estado</th><th>Asunto</th><th>Intento</th><?php else:?><th>Tipo</th><th>Referencia</th><th>Fecha</th><th>Archivo</th><?php endif;?></tr></thead><tbody><?php if(!$result['rows']):?><tr><td colspan="6"><?= empty_state('Sin registros','No hay información disponible para los filtros seleccionados.') ?></td></tr><?php endif;?><?php foreach($result['rows'] as $row):?><tr><?php if($section==='entregas'):$url=read_safe_reference_url($row['comprobante_url']);?><td><a class="table-link" href="/solicitudes/detalle.php?id=<?= (int)$row['solicitud_id'] ?>"><?= e($row['codigo_solicitud']) ?></a></td><td><a class="table-link" href="/viajes/detalle.php?id=<?= (int)$row['viaje_id'] ?>">#<?= (int)$row['viaje_id'] ?></a></td><td><?= status_tag($row['estado']) ?></td><td><?= e($row['receptor_nombre']?:'No aplica') ?></td><td><?php if($url):?><a class="table-link" target="_blank" rel="noopener noreferrer" href="<?= e($url) ?>">Ver comprobante</a><?php else:?><?= e($row['motivo_fallo']?:'Sin evidencia') ?><?php endif;?></td><?php elseif($section==='incidencias'):?><td><a class="table-link" href="/solicitudes/detalle.php?id=<?= (int)$row['solicitud_id'] ?>">#<?= (int)$row['solicitud_id'] ?></a></td><td><?= e($row['tipo_incidencia']) ?></td><td><?= status_tag($row['estado']) ?></td><td><?= e($row['responsable']) ?></td><td><?= format_utc_datetime($row['fecha_reporte']) ?></td><td><?php if($row['estado']!=='RESUELTA'&&has_permission('INCIDENCIAS_RESOLVER')):?><button class="button is-small button-secondary" hx-get="/entregas/incidencia_form.php?accion=resolver&incidencia_id=<?= (int)$row['incidencia_id'] ?>" hx-target="#modal-contenido">Resolver</button><?php endif;?></td><?php elseif($section==='notificaciones'):?><td><a class="table-link" href="/solicitudes/detalle.php?id=<?= (int)$row['solicitud_id'] ?>">#<?= (int)$row['solicitud_id'] ?></a></td><td><?= e($row['tipo_evento']) ?></td><td><?= status_tag($row['estado_envio']) ?></td><td><?= e($row['asunto']) ?></td><td><?= format_utc_datetime($row['fecha_intento']) ?></td><?php else:$url=read_safe_reference_url($row['archivo_url']);?><td><?= e($row['tipo_documento']) ?></td><td><?= e($row['numero_referencia']?:'—') ?></td><td><?= e($row['fecha_documento']?:'—') ?></td><td><?php if($url):?><a class="table-link" target="_blank" rel="noopener noreferrer" href="<?= e($url) ?>">Abrir referencia</a><?php else:?>Sin archivo<?php endif;?></td><?php endif;?></tr><?php endforeach;?></tbody></table></div><div class="pagination-wrap"><span><?= $total ?> resultado<?= $total===1?'':'s' ?></span><div class="buttons" hx-target="#entregas-resultado" hx-include="#entregas-filtros"><button class="button is-small" <?= $page<=1?'disabled':'' ?> hx-get="/entregas/lista.php?seccion=<?= e($section) ?>&pagina=<?= $page-1 ?>">Anterior</button><span class="pagination-info">Página <?= $page ?> de <?= $pages ?></span><button class="button is-small" <?= $page>=$pages?'disabled':'' ?> hx-get="/entregas/lista.php?seccion=<?= e($section) ?>&pagina=<?= $page+1 ?>">Siguiente</button></div></div>
